select
  to_regclass('public.aba_mastery_criterion_versions_v3') is not null as criterion_versions_ready,
  to_regclass('public.aba_maintenance_probes_v3') is not null as maintenance_probes_ready,
  to_regclass('public.aba_maintenance_probe_trials_v3') is not null as probe_trial_links_ready,
  to_regclass('public.aba_target_clinical_states_v3') is not null as clinical_states_ready,
  to_regclass('public.aba_target_clinical_state_events_v3') is not null as clinical_state_events_ready,
  to_regprocedure('public.publish_aba_mastery_criterion_version_v3(uuid,uuid,text,uuid,boolean,integer,numeric,integer,boolean,integer,numeric,integer,jsonb)') is not null as criterion_publisher_ready,
  to_regprocedure('public.finalize_aba_maintenance_probe_v3(uuid,text,uuid,timestamp with time zone)') is not null as probe_finalizer_ready,
  to_regprocedure('public.reconcile_aba_maintenance_probe_after_revision_v3()') is not null as probe_revision_reconciliation_ready,
  to_regprocedure('public.evaluate_aba_target_mastery_after_session_v3(uuid,uuid,text,text)') is not null as mastery_evaluator_ready,
  to_regprocedure('public.finalize_aba_session_measurements_v3(uuid,uuid,text,timestamp with time zone,uuid)') is not null as v3_measurement_finalizer_ready,
  to_regprocedure('public.complete_aba_session_v3(uuid,uuid,uuid,text,uuid,text,timestamp with time zone,text,jsonb,text,text)') is not null as atomic_hybrid_completion_ready,
  exists(select 1 from pg_indexes where indexname='ux_aba_maintenance_probes_v3_one_open_per_target_session') as one_open_probe_guard_ready,
  exists(select 1 from pg_trigger where tgname='zz_reconcile_aba_maintenance_probe_after_revision_v3' and not tgisinternal) as stale_probe_trigger_ready,
  not has_table_privilege('authenticated','public.aba_maintenance_probes_v3','SELECT') as browser_probes_blocked,
  not has_table_privilege('authenticated','public.aba_target_clinical_states_v3','SELECT') as browser_fsm_blocked,
  not has_function_privilege('authenticated','public.complete_aba_session_v3(uuid,uuid,uuid,text,uuid,text,timestamp with time zone,text,jsonb,text,text)','EXECUTE') as browser_completion_blocked,
  has_function_privilege('service_role','public.complete_aba_session_v3(uuid,uuid,uuid,text,uuid,text,timestamp with time zone,text,jsonb,text,text)','EXECUTE') as service_role_completion_ready,
  not exists(select 1 from public.aba_measurement_rollout_states_v3 where allow_new_v3_sessions) as no_new_v3_sessions_enabled;
